INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('trinkbrunnen-wien-winterpause-2026-hochstrahlbrunnen','Trinkbrunnen in Wien: 1.800 Brunnen gehen in die Winterpause','Wiener Wasser nimmt ab Ende Oktober rund 1.800 Trinkbrunnen und 55 Denkmalbrunnen außer Betrieb – zuerst am Stadtrand, zuletzt im 1. Bezirk. Im Frühjahr 2027 sprudeln sie wieder.','Die **Trinkbrunnen in Wien** gehen in die Winterpause: Wiener Wasser hat Ende Oktober damit begonnen, die rund 1.800 öffentlichen Trinkbrunnen und 55 Denkmalbrunnen der Stadt Schritt für Schritt außer Betrieb zu nehmen. Laut einer Aussendung der Stadt Wien vom 25. Oktober 2026 soll damit verhindert werden, dass Leitungen, Becken und Technik bei Minusgraden Schaden nehmen.

## Trinkbrunnen Wien: Warum die Brunnen abgedreht werden

Sobald die Temperaturen unter den Gefrierpunkt fallen, kann stehendes Wasser in Brunnen und Zuleitungen gefrieren und Bauteile sprengen. Deshalb werden sämtliche Anlagen vor dem ersten Frost vollständig entleert. Die Stadt verfolgt damit das Ziel, die Brunnen langfristig zu erhalten. Wiener-Wasser-Chef Paul Hellmeier weist darauf hin, dass das Einwintern je nach Brunnen aufwendig sei – deshalb starten die Arbeiten bereits Ende Oktober und nicht erst bei den ersten kalten Nächten.

## Reihenfolge: Vom Stadtrand in die Innere Stadt

Die Stilllegung folgt einem klaren Muster:

- Zuerst sind die Brunnen am **Stadtrand** an der Reihe, weil es dort früher friert als im dicht verbauten Zentrum.
- Danach arbeiten sich die Teams Richtung Stadtmitte vor.
- Als Letztes werden die Brunnen im **1. Bezirk** abgedreht.

Wer in den Außenbezirken unterwegs ist, sollte also schon in den kommenden Tagen damit rechnen, dass der gewohnte Trinkbrunnen kein Wasser mehr liefert. In der Innenstadt dürfte das Angebot noch etwas länger bestehen bleiben.

## Hochstrahlbrunnen am Schwarzenbergplatz als Ausnahme

Eine Sonderrolle spielt der Hochstrahlbrunnen am Schwarzenbergplatz. Obwohl er zentral liegt, wird er bereits ab Anfang November eingewintert. Grund ist das große Becken, das die Arbeiten deutlich komplexer und langwieriger macht als bei kleineren Anlagen.

Bei den Denkmalbrunnen reicht das bloße Entleeren nicht aus. Hier fallen zusätzliche Schritte an:

1. Die Becken werden gereinigt.
2. Wasserdüsen beziehungsweise Überläufe werden abmontiert.
3. Die Brunnen erhalten Abdeckungen, die sie über den Winter schützen.

Für den Hochstrahlbrunnen steht zudem eine größere Baustelle bevor: Die Stadt hat bereits im Februar angekündigt, das Wahrzeichen ab Ende 2027 umfassend zu sanieren. Dafür sind rund 12 Millionen Euro budgetiert, der Brunnen soll bis zum Saisonstart 2029 außer Betrieb bleiben. Erneuert werden unter anderem die Technik im Becken und in der darunterliegenden Kammer sowie die historischen Steinteile – in Abstimmung mit dem Bundesdenkmalamt.

## Wann die Brunnen wieder sprudeln

Laut Wiener Wasser werden die Trink- und Denkmalbrunnen ab dem **Frühjahr 2027** wieder in Betrieb genommen. Ein genaues Datum nennt die Stadt nicht; in der Regel hängt die Wiederinbetriebnahme von der Witterung ab, damit keine Frostschäden mehr drohen.

Bis dahin gilt für Spaziergänger, Läufer und Radfahrer: Wer unterwegs auf Wasser angewiesen ist, sollte im Winter eine eigene Flasche mitnehmen. Das Wiener Leitungswasser stammt aus den Hochquellenleitungen und kann zu Hause bedenkenlos abgefüllt werden.

Die Winterpause betrifft ausschließlich die öffentlichen Brunnen im Straßenraum und in Parks. Die Trinkwasserversorgung der Haushalte läuft selbstverständlich ganz normal weiter.','chronik','Wien','wien','news','Presseinfo Redaktion','/assets/img/artikel/trinkbrunnen-wien-winterpause-2026-hochstrahlbrunnen.webp','Stadt Wien – Wiener Wasser (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261025_OTS0011/wiener-wasser-schickt-brunnen-in-die-winterpause','published','2026-10-27T05:55:00.000Z','2026-10-27T05:45:34.915Z','Trinkbrunnen Wien: 1.800 Brunnen in Winterpause','Trinkbrunnen in Wien werden abgedreht: Wiener Wasser wintert 1.800 Trink- und 55 Denkmalbrunnen ein. Reihenfolge, Ausnahmen und Neustart im Frühjahr.','Trinkbrunnen Wien','["Trinkbrunnen Wien","Brunnen Wien Winterpause","Hochstrahlbrunnen","Wiener Wasser","Trinkbrunnen abgedreht","Denkmalbrunnen Wien","Wann werden Trinkbrunnen in Wien abgedreht","Hochstrahlbrunnen Sanierung 2027","Trinkbrunnen Wien wieder in Betrieb"]','Trinkbrunnen Wien: Ein Brunnen wird im Herbst für die Winterpause abgedeckt','An ornate historic stone fountain in a Vienna park in late autumn, empty basin being covered with wooden boards by a municipal worker seen from behind, fallen yellow leaves, misty cold morning, Viennese baroque buildings in soft background, no text, no logos, no readable signs','[{"q":"Wann werden die Trinkbrunnen in Wien abgedreht?","a":"Wiener Wasser beginnt Ende Oktober 2026 mit dem Einwintern. Zuerst sind Brunnen am Stadtrand dran, die im 1. Bezirk zuletzt. Der Hochstrahlbrunnen folgt ab Anfang November."},{"q":"Wann sind die Wiener Trinkbrunnen wieder in Betrieb?","a":"Laut Stadt Wien werden Trink- und Denkmalbrunnen ab dem Frühjahr 2027 wieder aufgedreht. Ein genaues Datum gibt es nicht."},{"q":"Wie viele Brunnen betrifft die Winterpause?","a":"Betroffen sind rund 1.800 öffentliche Trinkbrunnen sowie 55 Denkmalbrunnen, darunter der Hochstrahlbrunnen und der Donnerbrunnen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
